str_subtitle:   .byte "NES EDITION",$FF
str_pressstart: .byte "PRESS START",$FF
str_host:       .byte "HOST",$FF
str_you:        .byte "YOU",$FF
str_pickown:    .byte "PICK YOUR CASE - A",$FF
str_open1:      .byte "OPEN CASES LEFT",$FF
str_offer1:     .byte "BANKER OFFERS",$FF
str_dealprompt: .byte "A=DEAL   B=NO DEAL",$FF
str_deal_taken: .byte "YOU TOOK THE DEAL",$FF
str_swap1:      .byte "FINAL CASE REMAINS",$FF
str_swap2:      .byte "A=KEEP CASE  B=SWAP",$FF
str_final_result: .byte "YOUR CASE HELD",$FF
str_restart:    .byte "PRESS START",$FF

val_str_0: .byte "$1",$FF
val_str_1: .byte "$10",$FF
val_str_2: .byte "$50",$FF
val_str_3: .byte "$100",$FF
val_str_4: .byte "$500",$FF
val_str_5: .byte "$1000",$FF
val_str_6: .byte "$2500",$FF
val_str_7: .byte "$5000",$FF
val_str_8: .byte "$7500",$FF
val_str_9: .byte "$10000",$FF

val_str_lo: .byte <val_str_0,<val_str_1,<val_str_2,<val_str_3,<val_str_4,<val_str_5,<val_str_6,<val_str_7,<val_str_8,<val_str_9
val_str_hi: .byte >val_str_0,>val_str_1,>val_str_2,>val_str_3,>val_str_4,>val_str_5,>val_str_6,>val_str_7,>val_str_8,>val_str_9

case_num_1: .byte "1",$FF
