case_num_5: .byte "5",$FF
case_num_6: .byte "6",$FF
case_num_7: .byte "7",$FF
case_num_8: .byte "8",$FF
case_num_9: .byte "9",$FF
case_num_10: .byte "10",$FF

case_num_str_lo: .byte <case_num_1,<case_num_2,<case_num_3,<case_num_4,<case_num_5,<case_num_6,<case_num_7,<case_num_8,<case_num_9,<case_num_10
case_num_str_hi: .byte >case_num_1,>case_num_2,>case_num_3,>case_num_4,>case_num_5,>case_num_6,>case_num_7,>case_num_8,>case_num_9,>case_num_10

